"use strict";(self.webpackChunkiso_fns_docs=self.webpackChunkiso_fns_docs||[]).push([[53],{1109:e=>{e.exports=JSON.parse('{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","label":"Intro","href":"/docs/intro","docId":"intro"},{"type":"link","label":"Why Strings?","href":"/docs/why-strings","docId":"why-strings"},{"type":"link","label":"Comparison","href":"/docs/comparison","docId":"comparison"},{"type":"category","label":"API","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Instant","href":"/docs/api/Instant","docId":"api/Instant"},{"type":"link","label":"ZonedDateTime","href":"/docs/api/ZonedDateTime","docId":"api/ZonedDateTime"},{"type":"link","label":"Date","href":"/docs/api/Date","docId":"api/Date"},{"type":"link","label":"Time","href":"/docs/api/Time","docId":"api/Time"},{"type":"link","label":"DateTime","href":"/docs/api/DateTime","docId":"api/DateTime"},{"type":"link","label":"YearMonth","href":"/docs/api/YearMonth","docId":"api/YearMonth"},{"type":"link","label":"MonthDay","href":"/docs/api/MonthDay","docId":"api/MonthDay"},{"type":"link","label":"Duration","href":"/docs/api/Duration","docId":"api/Duration"}]},{"type":"link","label":"Time Zones and Resolving Ambiguity","href":"/docs/timezones-and-ambiguity","docId":"timezones-and-ambiguity"}]},"docs":{"api/Date":{"id":"api/Date","title":"Date","description":"An Iso.Date represents a calendar date. \\"Calendar date\\" refers to the concept of a date as expressed in everyday usage, independent of any time zone. For example, it could be used to represent an event on a calendar which happens during the whole day no matter which time zone it\'s happening in.","sidebar":"defaultSidebar"},"api/DateTime":{"id":"api/DateTime","title":"DateTime","description":"An Iso.DateTime represents a calendar date and wall-clock time, without any time zone.","sidebar":"defaultSidebar"},"api/Duration":{"id":"api/Duration","title":"Duration","description":"A Iso.Duration represents a duration of time which can be used in date/time arithmetic.","sidebar":"defaultSidebar"},"api/Instant":{"id":"api/Instant","title":"Instant","description":"An Iso.Instant is a single point in time (called \\"exact time\\"). No time zone is present. As such Iso.Instant has no concept of days, months or even hours.","sidebar":"defaultSidebar"},"api/MonthDay":{"id":"api/MonthDay","title":"MonthDay","description":"A Iso.MonthDay represents a particular day on the calendar, but without a year. For example, it could be used to represent a yearly recurring event, like \\"Bastille Day is on the 14th of July.\\"","sidebar":"defaultSidebar"},"api/Time":{"id":"api/Time","title":"Time","description":"An Iso.Time represents a wall-clock time without any time zone. \\"Wall-clock time\\" refers to the concept of a time as expressed in everyday usage \u2014 the time that you read off the clock on the wall. For example, it could be used to represent an event that happens daily at a certain time, no matter what time zone.","sidebar":"defaultSidebar"},"api/YearMonth":{"id":"api/YearMonth","title":"YearMonth","description":"A Iso.YearMonth represents a particular month on the calendar. For example, it could be used to represent a particular instance of a monthly recurring event, like \\"the June 2019 meeting\\".","sidebar":"defaultSidebar"},"api/ZonedDateTime":{"id":"api/ZonedDateTime","title":"ZonedDateTime","description":"An Iso.ZonedDateTime is a timezone-aware date/time type that represents a real event that has happened (or will happen) at a particular instant from the perspective of a particular region on Earth. As the broadest Iso type, Iso.ZonedDateTime can be considered a combination of a Iso.TimeZone, Iso.Instant, and Iso.DateTime.","sidebar":"defaultSidebar"},"comparison":{"id":"comparison","title":"Comparison","description":"| Feature | iso-fns | Moment | date-fns | Temporal Proposal | Luxon | js-joda |","sidebar":"defaultSidebar"},"intro":{"id":"intro","title":"Intro","description":"iso-fns is the only multi-domain, immutable, functional DateTime package for JavaScript. Its goal is to help you write bug free date/time logic without all the hassle. Inspired by date-fns, js-joda, and the Temporal Proposal for EcmaScript, iso-fns seeks to be simple, feature-rich, and performant.","sidebar":"defaultSidebar"},"timezones-and-ambiguity":{"id":"timezones-and-ambiguity","title":"Time Zones and Resolving Ambiguity","description":"Understanding Clock Time vs. Exact Time","sidebar":"defaultSidebar"},"why-strings":{"id":"why-strings","title":"Why Strings?","description":"JSON (JavaScript Object Notation) is now wildly popular (especially if you happen to be a JavaScript developer). JSON has three primitive types","sidebar":"defaultSidebar"}}}')}}]);